"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[24286],{24286:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/dream-painting.png\\"\\n          title=\\"몽환화\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"비채\\"\\n          publishedDate=\\"2014-05-20\\"\\n          isbn=\\"9791185014517\\"\\n          rating=4\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n등장인물이 많이 나오지만 다행히 화자는 세 사람이다.  \\n역시 일본 소설은 가계도를 그려 가며 봐야 이해가 잘 된다.  \\n<br>\\n프롤로그 1에서는 일명 MM 사건이라 불리는 묻지 마 살인 사건으로 이야기가 시작된다.  \\n프롤로그 2에서는 두 인물이 우연히 만나고 갑자기 이별 통보를 받는다.  \\n<br>\\n연관 없어 보이는 스토리들이 후반부쯤 서사의 연결고리가 생기고 하나의 퍼즐이 맞춰진다.  \\n<br>\\n원자력 연구에 대해 고심하는 장면이 나오는데, <mark>몽환화</mark>처럼 경각심을 주기 위한 것 같다.  \\n<br>\\n이 작품은 작가가 오랫동안 고심 끝에 완성한 작품이라고 한다.  \\n```히가시노 게이고```만의 색을 잘 보여주는 대표작 같다."}')}}]);